settings:
{
  // The dialect of every query of the project, unless its file names another.
  "dialect": "postgres",
  // Every query of this project is generated as SQL alone, the constants and the token methods.  A query with models
  // would need a sidecar beside its file.
  "output": "Sql",
  // Token validation is off, so that a query whose markers do not turn it back on does not check its arguments.
  "generatorParameters": ["sort-input", "token-validation=off"],
}
{
  // The end of every search for settings files in this repository.  A settings file above the checkout, such as the
  // main checkout's when this is a worktree under .claude/worktrees/, would otherwise reach every project here that
  // has no root file of its own.
  "root": true,
}

input:
/* A file without a name marker is one query, named after the file.  Its marker puts its constant on the type. */
-- member-location: class
SELECT COUNT(*) FROM users;
